'use strict';
let padTool='play',rackScope='master',rackTab='rack',masterRack=null,rackBypass=false,redoStates=[],repeatHandle=null,stretchJob=null;
function tempo(){return state.bpm}
const repeats=new Map(),padFxMaps=new WeakMap(),offlineRacks=new WeakMap();
function createStudioRack(c,input,destination,settings){const first=c.createGain(),middle=c.createGain();input.connect(first);const slots=StudioModel.rack(settings);let lastBPM=tempo(),graphs=[PocketFX.create(c,first,middle,slots[0]),PocketFX.create(c,middle,destination,slots[1])];return {set(values){const s=StudioModel.rack(values);if(lastBPM!==tempo()){graphs.forEach(g=>g.dispose());graphs=[PocketFX.create(c,first,middle,s[0]),PocketFX.create(c,middle,destination,s[1])];lastBPM=tempo()}else graphs.forEach((g,i)=>g.set(s[i]))},dispose(){try{input.disconnect(first)}catch{}graphs.forEach(g=>g.dispose());first.disconnect();middle.disconnect()}}}
function studioPadDestination(p,index,c,destination){const settings=rackBypass&&rackScope==='pad'&&index===state.selected?[PocketFX.normalized({type:'off'}),PocketFX.normalized({type:'off'})]:StudioModel.rack(p.fx);if(settings.every(s=>s.type==='off'||s.wet===0))return destination;let map=padFxMaps.get(c);if(!map){map=new Map();padFxMaps.set(c,map)}let entry=map.get(index);if(!entry){const input=c.createGain(),output=c.createGain();output.connect(destination);entry={input,output,graph:createStudioRack(c,input,output,settings),destination};map.set(index,entry)}else if(entry.destination!==destination){entry.output.disconnect();entry.output.connect(destination);entry.destination=destination}entry.graph.set(settings);return entry.input}
function syncStudioRacks(){if(masterRack)masterRack.set(rackBypass&&rackScope==='master'?[{type:'off'},{type:'off'}]:state.masterFX);if(audio.ctx){const map=padFxMaps.get(audio.ctx);if(map)for(const [i,e]of map)e.graph.set(rackBypass&&rackScope==='pad'&&i===state.selected?[{type:'off'},{type:'off'}]:state.pads[i].fx)}}
const unlockCore=unlock;unlock=async()=>{await unlockCore();if(typeof PocketLoFi!=='undefined')await PocketLoFi.prepare(audio.ctx);if(!masterRack){audio.input.disconnect(audio.hp);masterRack=createStudioRack(audio.ctx,audio.input,audio.hp,state.masterFX)}syncStudioRacks()};
function toggleMute(i){remember();state.pads[i].muted=!state.pads[i].muted;if(state.pads[i].muted)audio.stop(i);state.selected=i;changed();render()}
function toggleSolo(i){remember();const on=!state.pads[i].solo;for(const p of state.pads)p.solo=false;state.pads[i].solo=on;if(on)for(const v of [...audio.voices])if(v.index!==i)audio.release(v);state.selected=i;changed();render()}
function handlePadTool(i){if(padTool==='play')return false;if(padTool==='select'){state.selected=i;renderSelection();return true}if(padTool==='mute')toggleMute(i);else toggleSolo(i);return true}
$$('[data-pad-tool]').forEach(b=>b.onclick=()=>{padTool=b.dataset.padTool;$$('[data-pad-tool]').forEach(el=>{const on=el===b;el.classList.toggle('active',on);el.setAttribute('aria-pressed',on)})});
function renderDirect(){const p=state.pads[state.selected];$('#quickVolume').value=p.volume*100;for(const [id,on]of [['quickMute',p.muted],['quickSolo',p.solo]]){$('#'+id).classList.toggle('active',on);$('#'+id).setAttribute('aria-pressed',on)}if(screen==='remix'&&rackTab==='rack')renderRackTarget();if(typeof renderMidiBadge==='function')renderMidiBadge()}
const renderCore=render;render=()=>{renderCore();renderDirect();syncStudioRacks();if(screen==='remix'&&rackTab==='rack')renderRack()};const selectionCore=renderSelection;renderSelection=()=>{selectionCore();renderDirect()};
$('#quickMute').onclick=()=>toggleMute(state.selected);$('#quickSolo').onclick=()=>toggleSolo(state.selected);$('#quickStop').onclick=()=>{audio.stop(state.selected);if(typeof midiStopPad==='function')midiStopPad(state.selected)};
$('#quickVolume').onpointerdown=remember;$('#quickVolume').oninput=()=>{const p=state.pads[state.selected];p.volume=+$('#quickVolume').value/100;if(audio.ctx)for(const v of audio.voices)if(v.index===state.selected&&!v.stopped)v.g.gain.setTargetAtTime(p.volume*v.velocity,audio.ctx.currentTime,.01);changed()};
$('#editBack').onclick=()=>setScreen('play');$('#mute').onclick=()=>toggleMute(state.selected);$('#solo').onclick=()=>toggleSolo(state.selected);
const rememberCore=remember;remember=()=>{redoStates=[];$('#redo').disabled=true;rememberCore()};const undoCore=$('#undo').onclick;$('#undo').onclick=()=>{if(!history.length)return;redoStates.push(M.clone(state));undoCore();$('#redo').disabled=!redoStates.length;syncStudioRacks();if(typeof refreshMidiUI==='function')refreshMidiUI()};$('#redo').onclick=()=>{if(!redoStates.length)return;history.push(M.clone(state));stop();state=redoStates.pop();render();changed();$('#redo').disabled=!redoStates.length;if(typeof refreshMidiUI==='function')refreshMidiUI()};
function stopRepeats(){for(const token of [...repeats.keys()])repeats.delete(token);clearInterval(repeatHandle);repeatHandle=null}
const hitCore=hit;hit=async(i,token=null,pitch=0,options={})=>{const tool=padTool;const promise=hitCore(i,token,pitch,options);if(ready&&token!==null&&!options.repeat&&(tool==='play'||options.fromMidi)&&+$('#noteRepeat').value&&state.pads[i].mode!=='loop'){await promise;if(!pressed.has(token))return;repeats.set(token,{i,pitch,options,next:performance.now()+60/state.bpm*4000/(+$('#noteRepeat').value)});if(!repeatHandle)repeatHandle=setInterval(()=>{const now=performance.now();for(const [token,r]of repeats){if(!pressed.has(token)){repeats.delete(token);continue}if(now>=r.next){hitCore(r.i,token,r.pitch,{...r.options,repeat:true});r.next=now+60/state.bpm*4000/(+$('#noteRepeat').value||16)}}if(!repeats.size)stopRepeats()},8)}else return promise};
const releaseCore=release;release=token=>{repeats.delete(token);releaseCore(token)};const stopCore=stop;stop=()=>{stopRepeats();stopCore();if(typeof midiPanic==='function')midiPanic();if(typeof midiTransportOut==='function')midiTransportOut(252)};$('#noteRepeat').onchange=()=>{if(!+$('#noteRepeat').value)stopRepeats()};
for(const [id,key]of [['release','release'],['choke','choke']]){$('#'+id).onpointerdown=remember;$('#'+id).onchange=()=>{state.pads[state.selected][key]=+$('#'+id).value;changed()}}const editorCore=renderEditor;renderEditor=()=>{editorCore();$('#release').value=state.pads[state.selected].release;$('#choke').value=state.pads[state.selected].choke};
$('#stretchApply').onclick=()=>{if(stretchJob){message('Un étirement est déjà en cours.');return}const owner=state,p=state.pads[state.selected],original=p.data,right=p.right,from=Math.floor(p.start*p.data.length),to=Math.floor(p.end*p.data.length),ratio=Math.min(2,Math.max(.5,(+$('#stretchPercent').value||100)/100)),worker=new Worker('stretch-worker.js?v=2');stretchJob=worker;$('#stretchApply').disabled=true;$('#stretchStatus').textContent='Calcul…';const clean=()=>{worker.terminate();stretchJob=null;$('#stretchApply').disabled=false};worker.onerror=e=>{clean();$('#stretchStatus').textContent=e.message};worker.onmessage=e=>{if(e.data.error){clean();$('#stretchStatus').textContent=e.data.error;return}if(!e.data.channels)return;const [left,outRight]=e.data.channels;clean();if(state!==owner||!state.pads.includes(p)||p.data!==original||p.right!==right){$('#stretchStatus').textContent='Annulé : le son a changé.';return}try{audioMemory(state.pads.indexOf(p),left,outRight);remember();audio.stop(state.pads.indexOf(p));p.data=left;p.right=outRight||null;p.start=0;p.end=1;changed();render();$('#stretchStatus').textContent='Durée ×'+ratio.toFixed(2)+' · hauteur conservée'}catch(err){$('#stretchStatus').textContent=err.message}};const channels=[p.data.slice(from,to),...(p.right?[p.right.slice(from,to)]:[])];worker.postMessage({channels,ratio,rate:RATE},channels.map(c=>c.buffer))};
function setRackTab(tab){rackTab=tab;$('#rackView').hidden=tab!=='rack';$('#gestureView').hidden=tab==='rack';$('#rackTab').classList.toggle('active',tab==='rack');$('#gestureTab').classList.toggle('active',tab!=='rack');if(tab==='rack')renderRack()}
$('#rackTab').onclick=()=>setRackTab('rack');$('#gestureTab').onclick=()=>setRackTab('gesture');
function rackSettings(){return rackScope==='master'?(state.masterFX||(state.masterFX=M.rack())):(state.pads[state.selected].fx||(state.pads[state.selected].fx=M.rack()))}
function renderRackTarget(){$('#rackTargetName').textContent=rackScope==='master'?'MASTER':label(state.selected)+' · '+state.pads[state.selected].name;$('#rackScope').value=rackScope;$('#rackTargetName').hidden=rackScope==='pad';$('#rackPad').hidden=rackScope!=='pad';if(rackScope==='pad'){const select=$('#rackPad');select.replaceChildren();for(let i=0;i<64;i++)if(state.pads[i].data.length>1||i===state.selected){const o=document.createElement('option');o.value=i;o.textContent=label(i)+' · '+state.pads[i].name;select.append(o)}select.value=state.selected}$('#rackBypass').classList.toggle('active',rackBypass);$('#rackBypass').setAttribute('aria-pressed',rackBypass)}
function effectChoices(select){const groups=[['Aucun',['off']],['Délais',['lib:delay','lib:diffdelay','lib:tapedelay','lib:sampledelay','lib:comb']],['Réverbérations',['lib:small','lib:medium','lib:large','lib:spring']],['Filtres / modulation',['lib:hp','lib:lp','lib:bp','lib:wah','lib:chorus','lib:ensemble','lib:multichorus','lib:phaser','lib:flanger','lib:pan','ring']],['Dynamique',['lib:buscomp','lib:limiter','lib:pumper','lib:transient','lib:gate']],['Couleur',['lib:amp','lib:tube','lib:clipper','lib:vintage','lib:vinyl','lib:tape','lib:lofi']]];for(const [name,types]of groups){const group=document.createElement('optgroup');group.label=name;for(const type of types){const o=document.createElement('option');o.value=type;o.textContent=PocketFX.names[type]?.replace(' · avancé','')||type;group.append(o)}select.append(group)}}
function changeRack(slot,value){remember();rackSettings()[slot]=PocketFX.normalized(value);rackBypass=false;syncStudioRacks();changed();renderRack()}
function renderRack(){renderRackTarget();const host=$('#rackSlots');host.replaceChildren();const slots=StudioModel.rack(rackSettings());for(let i=0;i<2;i++){const p=slots[i],box=document.createElement('article');box.className='rack-slot';const head=document.createElement('div');head.className='slot-head';const number=document.createElement('span');number.textContent='FX '+(i+1);const select=document.createElement('select');select.setAttribute('aria-label','Effet '+(i+1));effectChoices(select);select.value=p.type;select.onchange=()=>changeRack(i,{type:select.value,wet:.35});head.append(number,select);box.append(head);const fields=p.type.startsWith('lib:')?PocketLibrary.schemas[p.type.slice(4)][1].filter(f=>f.key!=='mix'):p.type==='off'?[]:[{key:'amount',label:'Intensité',min:0,max:100,value:40},{key:'character',label:'Caractère',min:0,max:100,value:35}];if(p.type!=='off'){const mix=document.createElement('label');mix.className='rack-mix';const mixName=document.createElement('span');mixName.textContent='Mélange';const value=document.createElement('output');value.textContent=Math.round(p.wet*100)+' %';const input=document.createElement('input');input.type='range';input.min=0;input.max=100;input.value=p.wet*100;input.setAttribute('aria-label','Mélange effet '+(i+1));input.onpointerdown=remember;input.oninput=()=>{rackSettings()[i]=PocketFX.normalized({...p,wet:+input.value/100});value.textContent=input.value+' %';syncStudioRacks();changed()};mix.append(mixName,value,input);box.append(mix);const controls=document.createElement('div');controls.className='rack-fields';for(const f of fields){const label=document.createElement('label');label.textContent=f.label+(f.unit?' · '+f.unit:'');const el=document.createElement(f.values?'select':'input');if(f.values){for(const text of f.values){const o=document.createElement('option');o.value=text;o.textContent=text;el.append(o)}el.value=p.params?.[f.key]??f.value}else{el.type='number';el.min=f.min;el.max=f.max;el.step=(f.max-f.min)<10?.01:1;el.value=p.params?.[f.key]??(['amount','character'].includes(f.key)?p[f.key]*100:f.value)}el.onchange=()=>{const current=rackSettings()[i],params={...(current.params||{})},v=f.values?el.value:Math.max(f.min,Math.min(f.max,+el.value));if(['amount','character'].includes(f.key))changeRack(i,{...current,[f.key]:v/100});else{params[f.key]=v;changeRack(i,{...current,params})}};label.append(el);controls.append(label)}box.append(controls)}host.append(box)}}
$('#rackScope').onchange=()=>{rackScope=$('#rackScope').value;rackBypass=false;syncStudioRacks();renderRack()};$('#rackBypass').onclick=()=>{rackBypass=!rackBypass;syncStudioRacks();renderRackTarget()};
const resetCore=$('#fxReset').onclick;$('#fxReset').onclick=()=>{if(rackTab==='gesture')resetCore();else{remember();const settings=rackSettings();settings[0]=PocketFX.normalized({type:'off'});settings[1]=PocketFX.normalized({type:'off'});rackBypass=false;syncStudioRacks();changed();renderRack()}};
// Scale choices are independent from the selected sample's original acoustic pitch.
function buildScale(){const kind=$('#scale').value,intervals=kind==='major'?[0,2,4,5,7,9,11,12]:kind==='chromatic'?Array.from({length:13},(_,i)=>i):[0,2,3,5,7,8,10,12];$('#keys').replaceChildren();for(const pitch of intervals){const b=document.createElement('button');b.textContent=pitch===0?'Base':(pitch>0?'+':'')+pitch;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);b.classList.add('hit');hit(state.selected,'key:'+e.pointerId,pitch+octave*12,{ignoreTool:true,gate:true})};const off=e=>{b.classList.remove('hit');release('key:'+e.pointerId)};b.onpointerup=off;b.onpointercancel=off;b.onlostpointercapture=off;b.onclick=e=>{if(e.detail===0)hit(state.selected,null,pitch+octave*12,{ignoreTool:true,gate:true})};$('#keys').append(b)}}$('#scale').onchange=()=>{releaseTouches();buildScale()};buildScale();renderDirect();

$('#rackPad').onchange=()=>{state.selected=+$('#rackPad').value;state.bank=Math.floor(state.selected/16);rackBypass=false;syncStudioRacks();renderRack()};
